static ConfigurationModel loadConfigurationFile(File configFile,String workingDirectory){
  LOG.debug("Loading config file: " + configFile.getAbsolutePath());
  if (!configFile.isAbsolute() && workingDirectory != null) {
    try {
      File temporaryFile=new File(workingDirectory,configFile.getPath());
      if (temporaryFile.exists()) {
        configFile=temporaryFile;
      }
    } catch (SecurityException e) {
      throw new FlywayException("Security check failed when accessing config file: " + configFile.getAbsolutePath(), e);
    }
  }
  try {
    return ObjectMapperFactory.getObjectMapper(configFile.toString()).configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES,false).readerFor(ConfigurationModel.class).readValue(configFile);
  } catch (IOException e) {
    throw new FlywayException("Unable to load config file: " + configFile.getAbsolutePath(),e);
  }
}
